l !== ''): ?><div class="small text-danger"><i class="fa-solid fa-circle-info me-1" aria-hidden="true"></i><?= htmlspecialchars($errorLabel) ?></div><?php endif; ?></td><td><?php if (!empty($row['invoice_id'])): ?><a href="<?= htmlspecialchars(url_for('admin/abrechnung/rechnung/' . (int) $row['invoice_id']), ENT_QUOTES) ?>"><?= htmlspecialchars((string) ($row['invoice_number'] ?: '#' . $row['invoice_id'])) ?></a><?php else: ?>—<?php endif; ?></td><td><div class="dropdown"><button class="btn btn-sm btn-outline-secondary dropdown-toggle" data-bs-toggle="dropdown" type="button"><i class="fa-solid fa-gear" aria-hidden="true"></i></button><ul class="dropdown-menu dropdown-menu-end"><li><form method="post" action="<?= htmlspecialchars(url_for('admin/abrechnung/pruefung/' . (int) $row['id'] . '/abrechenbarkeit'), ENT_QUOTES) ?>" class="px-3 py-2"><input type="hidden" name="eligibility" value="<?= ($row['billing_eligibility'] ?? '') === 'billable' ? 'not_billable' : 'billable' ?>"><input class="form-control form-control-sm mb-2" name="reason" placeholder="Grund (bei nicht abrechenbar)"><button class="btn btn-sm btn-primary" type="submit">Abrechenbarkeit ändern</button></form></li><?php if (current_user_is_superadmin() && $status === 'exported'): ?><li><hr class="dropdown-divider"></li><li><form method="post" action="<?= htmlspecialchars(url_for('admin/abrechnung/pruefung/' . (int) $row['id'] . '/export-zuruecksetzen'), ENT_QUOTES) ?>" class="px-3 py-2"><input type="hidden" name="confirm" value="1"><input class="form-control form-control-sm mb-2" name="reason" placeholder="Reset-Grund" required><button class="btn btn-sm btn-danger" type="submit" onclick="return confirm('Diese Prüfung ist bereits abgerechnet. Wirklich zurücksetzen?');"><i class="fa-solid fa-triangle-exclamation me-1" aria-hidden="true"></i>Export zurücksetzen</button></form></li><?php endif; ?></ul></div></td></tr><?php endforeach; ?>
