<script>
(() => {
const source = document.getElementById('billing-actions-panel');
if (!source) return;
const boxes = [...source.querySelectorAll('.billing-check')];
const scope = source.querySelector('[name="selection_scope"]');
const selectionKey = 'pruefapp-billing-selection:' + window.location.pathname + '?' + (() => { const query = new URLSearchParams(window.location.search); query.delete('page'); return query.toString(); })();
let persisted = [];
try { persisted = JSON.parse(sessionStorage.getItem(selectionKey) || '[]').map(Number).filter(Number.isInteger); } catch (_) {}
boxes.forEach(box => { box.checked = persisted.includes(Number(box.value)); });
const selectedIds = () => [...new Set([...persisted, ...boxes.filter(box => box.checked).map(box => Number(box.value))])].filter(Number.isInteger);
const remember = () => { persisted = [...new Set([...persisted.filter(id => !boxes.some(box => Number(box.value) === id)), ...boxes.filter(box => box.checked).map(box => Number(box.value))])]; try { sessionStorage.setItem(selectionKey, JSON.stringify(persisted)); } catch (_) {} };
const updateFilterQuery = () => { const target = source.querySelector('[name="filter_query"]'); if (target) target.value = window.location.search; };
boxes.forEach(box => box.addEventListener('change', remember));
document.getElementById('billing-all')?.addEventListener('change', event => { boxes.forEach(box => { box.checked = event.target.checked; }); remember(); });
document.getElementById('billing-mark-page')?.addEventListener('click', () => { boxes.forEach(box => { box.checked = true; }); remember(); });
document.getElementById('billing-unmark-page')?.addEventListener('click', () => { boxes.forEach(box => { box.checked = false; }); remember(); });
document.getElementById('billing-mark-all')?.addEventListener('click', () => { if (scope) scope.value = 'all'; boxes.forEach(box => { box.checked = true; }); remember(); });
source.addEventListener('submit', event => {
  source.querySelectorAll('[data-generated-billing-id]').forEach(node => node.remove());
  updateFilterQuery();
  const mode = scope?.value || 'selection';
  if (mode === 'all') return;
  const ids = mode === 'page' ? boxes.map(box => Number(box.value)) : selectedIds();
  if (ids.length === 0) { event.preventDefault(); window.alert('Bitte mindestens eine Prüfung auswählen.'); return; }
  ids.forEach(id => { const input = document.createElement('input'); input.type = 'hidden'; input.name = 'inspection_ids[]'; input.value = String(id); input.dataset.generatedBillingId = '1'; source.append(input); });
});
document.querySelector('[data-billing-csv-download]')?.addEventListener('click', () => {
  updateFilterQuery();
  const mode = scope?.value || 'selection';
  const ids = mode === 'all' ? [] : (mode === 'page' ? boxes.map(box => Number(box.value)) : selectedIds());
  if (mode !== 'all' && ids.length === 0) {
    window.alert('Bitte mindestens eine Prüfung für den CSV-Download auswählen.');
    return;
  }
  // Ein Download darf nicht über XHR/HTMX laufen: Der Browser muss den
  // Content-Disposition-Header selbst verarbeiten und die Datei speichern.
  const download = document.createElement('form');
  download.method = 'post';
  // `action` is also the name of submitted buttons. Accessing `.action`
  // would therefore yield a RadioNodeList instead of the form URL.
  download.action = source.getAttribute('action') || window.location.href;
  download.hidden = true;
  const action = document.createElement('input');
  action.type = 'hidden'; action.name = 'action'; action.value = 'csv';
  download.append(action);
  [['selection_scope', mode], ['filter_query', source.querySelector('[name="filter_query"]')?.value || '']].forEach(([name, value]) => { const input = document.createElement('input'); input.type = 'hidden'; input.name = name; input.value = value; download.append(input); });
  ids.forEach(id => {
    const input = document.createElement('input');
    input.type = 'hidden'; input.name = 'inspection_ids[]'; input.value = String(id);
    download.append(input);
  });
  document.body.append(download);
  download.submit();
  download.remove();
});
})();
document.body.addEventListener('billing-refresh', () => {
  if (window.htmx) htmx.ajax('GET', window.location.href, {target:'#billing-content', swap:'outerHTML', pushUrl:false});
});
</script>
<script>
document.querySelector('form[hx-get]')?.addEventListener('submit', () => {
  document.querySelectorAll('[form="billing-filter-form"]').forEach(field => {
    const existing = document.querySelector('form[hx-get] [name="' + field.name + '"]');
    if (existing) existing.value = field.value;
    else { const hidden = document.createElement('input'); hidden.type = 'hidden'; hidden.name = field.name; hidden.value = field.value; document.querySelector('form[hx-get]').appendChild(hidden); }
  });
});
</script>
</div>
